/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { firstValueFrom, Observable, of, throwError } from 'rxjs';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { RepositoryProvider, UploadProgress } from '../repository/provider/repository-provider.interface';
import { OfflineQueueService } from './offline-queue.service';
import { OFFLINE_DB_NAME } from './offline.model';

const NETWORK = () => new TypeError('Failed to fetch');

/** Provider en memoria; `down` simula la falta de red y `reject` el rechazo de una clave. */
class MemoryProvider implements RepositoryProvider<any, any> {
  rows = new Map<string, any>();
  calls: string[] = [];
  down = false;
  reject = new Set<string>();

  private guard<V>(name: string, key: string, run: () => V): Observable<V> {
    if (this.down) {
      return throwError(NETWORK);
    }
    this.calls.push(name + ':' + key);
    if (this.reject.has(key)) {
      return throwError(() => ({ status: 400, message: 'invalid ' + key }));
    }
    return of(run());
  }
  acl(key: string | null) {
    return this.guard('acl', key ?? '', () => ({ allows: [{ name: 'update', allowed: true }], key }) as any);
  }
  list() {
    return this.guard('list', '', () => ({ content: [...this.rows.values()], hasNext: false, next: null }));
  }
  retrieve(key: string) {
    if (!this.down && !this.rows.has(key)) {
      return throwError(() => ({ status: 404 }));
    }
    return this.guard('retrieve', key, () => this.rows.get(key));
  }
  add(item: any) {
    return this.guard('add', item.uid, () => (this.rows.set(item.uid, item), item));
  }
  update(key: string, item: any) {
    return this.guard('update', key, () => (this.rows.set(key, item), item));
  }
  patch(key: string, data: any) {
    return this.guard('patch', key, () => {
      const value = { ...this.rows.get(key), ...data };
      this.rows.set(key, value);
      return value;
    });
  }
  delete(key: string) {
    return this.guard('delete', key, () => void this.rows.delete(key));
  }
  downloadFile(): Observable<any> {
    return throwError(() => new Error('no'));
  }
  storeFile(_endpoint: string, _name: string, file: File) {
    return this.guard('storeFile', file.name, () =>
      new UploadProgress().innerData('https://server/files/' + file.name),
    );
  }
}

describe('OfflineQueueService', () => {
  let queue: OfflineQueueService;
  let sites: MemoryProvider;
  let floors: MemoryProvider;
  let siteApi: RepositoryProvider<any, any>;
  let floorApi: RepositoryProvider<any, any>;
  /** Espera de la subida automática; `0` (sin subida automática) salvo en sus pruebas. */
  const autoDelay = signal<number>(0);

  beforeEach(async () => {
    autoDelay.set(0);
    TestBed.configureTestingModule({
      providers: [
        { provide: OFFLINE_DB_NAME, useValue: 'offline-test-' + Math.random() },
        {
          provide: RuntimeConfigService,
          useValue: {
            value: (path: string) =>
              path === 'data.offline-sync-delay' ? autoDelay : signal(path === 'data.offline' ? true : undefined),
            value$: () => of({}),
          },
        },
        { provide: AppStateService, useValue: { tenant$: of('t1'), user$: () => of({ uid: 'u1' }) } },
        { provide: NotifyService, useValue: jasmine.createSpyObj('NotifyService', ['info', 'success', 'error']) },
      ],
    });
    queue = TestBed.inject(OfflineQueueService);
    TestBed.tick();
    sites = new MemoryProvider();
    floors = new MemoryProvider();
    siteApi = queue.wrap({ key: 'uid', name: 'site', provider: sites, entity: { id: 'uid', display: 'name' } });
    floorApi = queue.wrap({ key: 'uid', name: 'floor', provider: floors });
    await queue.ready();
  });

  it('writes directly while online and nothing is pending', async () => {
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
    expect(sites.rows.has('s1')).toBeTrue();
    expect(queue.pending()).toBe(0);
  });

  it('queues on a network failure and keeps queueing to preserve the order', async () => {
    sites.down = true;
    const saved = await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
    expect(saved).toEqual({ uid: 's1', name: 'A' });
    sites.down = false;
    // Con cambios pendientes también se encola aunque haya red; el patch se fusiona con el alta
    await firstValueFrom(siteApi.patch('s1', { name: 'B' }));
    expect(queue.pending()).toBe(1);
    expect(queue.ops()[0].kind).toBe('add');
    expect(queue.ops()[0].payload.name).toBe('B');
    expect(queue.ops()[0].uncertain).toBeTrue();
    // La entidad se lee de su copia local
    expect(await firstValueFrom(siteApi.retrieve('s1'))).toEqual({ uid: 's1', name: 'B' });
  });

  it('syncs one by one, checking an uncertain creation before repeating it', async () => {
    sites.down = true;
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
    sites.down = false;
    sites.rows.set('s1', { uid: 's1', name: 'A' }); // la petición sí llegó
    await firstValueFrom(floorApi.add({ uid: 'f1', site: { $ref: 's1' } }));

    const result = await queue.sync();

    expect(result).toBe('done');
    expect(queue.pending()).toBe(0);
    expect(sites.calls).toEqual(['retrieve:s1']);
    expect(floors.calls).toEqual(['add:f1']);
  });

  it('stops at the first error and blocks what depends on it', async () => {
    sites.down = true;
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
    await firstValueFrom(floorApi.add({ uid: 'f1', site: { $ref: 's1' } }));
    await firstValueFrom(siteApi.add({ uid: 's2', name: 'B' }));
    sites.down = false;
    sites.reject.add('s1');

    expect(await queue.sync()).toBe('stopped');

    const states = queue.ops().map((op) => [op.key, op.status]);
    expect(states).toEqual([
      ['s1', 'failed'],
      ['f1', 'blocked'],
      ['s2', 'pending'],
    ]);
    expect(queue.ops()[0].error?.message).toBe('invalid s1');
    expect(floors.calls).toEqual([]);

    // Seguir con el resto: sube lo independiente y deja lo fallido
    expect(await queue.sync('skip')).toBe('stopped');
    expect(queue.ops().map((op) => op.key)).toEqual(['s1', 'f1']);
    expect(sites.rows.has('s2')).toBeTrue();
  });

  it('retries after fixing the data, unblocking the dependents', async () => {
    sites.down = true;
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'bad' }));
    await firstValueFrom(floorApi.add({ uid: 'f1', site: { $ref: 's1' } }));
    sites.down = false;
    sites.reject.add('s1');
    await queue.sync();

    sites.reject.clear();
    await queue.edit(queue.ops()[0], { uid: 's1', name: 'good' });
    expect(await queue.sync()).toBe('done');
    expect(sites.rows.get('s1').name).toBe('good');
    expect(floors.rows.has('f1')).toBeTrue();
  });

  it('discards an operation together with its dependents', async () => {
    sites.down = true;
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
    await firstValueFrom(floorApi.add({ uid: 'f1', site: { $ref: 's1' } }));
    await firstValueFrom(siteApi.add({ uid: 's2', name: 'B' }));

    await queue.discard(queue.ops()[0]);

    expect(queue.ops().map((op) => op.key)).toEqual(['s2']);
  });

  it('keeps attachments locally and replaces their URL when uploaded', async () => {
    sites.down = true;
    queue.markOffline();
    const file = new File(['img'], 'photo.png', { type: 'image/png' });
    const stored = await firstValueFrom(siteApi.storeFile('/-/temp', 'file', file));
    const url: string = stored.data;
    expect(url.startsWith('offline-file://')).toBeTrue();
    const blob = await firstValueFrom(siteApi.downloadFile(url));
    expect(blob.name).toBe('photo.png');
    await firstValueFrom(siteApi.add({ uid: 's1', photo: url }));

    sites.down = false;
    expect(await queue.sync()).toBe('done');
    expect(sites.rows.get('s1').photo).toBe('https://server/files/photo.png');
  });

  it('stops without failing when the network drops during the sync', async () => {
    sites.down = true;
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));

    expect(await queue.sync()).toBe('offline');
    expect(queue.ops()[0].status).toBe('pending');
    expect(queue.online()).toBeFalse();
  });

  it('serves the last read when offline', async () => {
    sites.rows.set('s1', { uid: 's1', name: 'A' });
    await firstValueFrom(siteApi.retrieve('s1'));
    await new Promise((resolve) => setTimeout(resolve, 20));
    sites.down = true;
    expect(await firstValueFrom(siteApi.retrieve('s1'))).toEqual({ uid: 's1', name: 'A' });
  });

  it('serves the stored ACL offline, falling back to the generic one for unknown items', async () => {
    await firstValueFrom(siteApi.acl!(null));
    await firstValueFrom(siteApi.acl!('s1'));
    await new Promise((resolve) => setTimeout(resolve, 20));
    sites.down = true;
    queue.markOffline();

    expect(((await firstValueFrom(siteApi.acl!('s1'))) as any).key).toBe('s1');
    // Creado sin conexión: nunca se pidió su ACL
    expect(((await firstValueFrom(siteApi.acl!('new'))) as any).key).toBeNull();
  });

  it('shows pending creations in the first page of matching lists', async () => {
    sites.rows.set('s0', { uid: 's0', name: 'Old' });
    sites.down = true;
    await firstValueFrom(siteApi.add({ uid: 's1', name: 'New' }));
    sites.down = false;
    queue['onlineSignal'].set(true);

    const page = await firstValueFrom(siteApi.list({}));
    expect(page.content.map((item: any) => item.uid)).toEqual(['s1', 's0']);
    const filtered = await firstValueFrom(siteApi.list({ name: 'Old' }));
    expect(filtered.content.map((item: any) => item.uid)).toEqual(['s0']);
  });

  describe('automatic sync', () => {
    const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

    /** Encola un alta sin red y deja la red de vuelta (el navegador aún no lo sabe). */
    async function queueWhileDown(): Promise<void> {
      sites.down = true;
      await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
      sites.down = false;
    }

    it('uploads on its own once the connection stays up for the delay', async () => {
      autoDelay.set(80);
      await queueWhileDown();
      queue['onlineSignal'].set(true);
      TestBed.tick();

      await wait(40);
      expect(sites.rows.has('s1')).toBeFalse();
      await wait(150);
      expect(sites.rows.has('s1')).toBeTrue();
      expect(queue.pending()).toBe(0);
    });

    it('starts waiting again when the connection drops before the delay', async () => {
      autoDelay.set(100);
      await queueWhileDown();
      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(60);
      // Corte breve (p. ej. un túnel): se desarma y la espera vuelve a empezar
      queue['onlineSignal'].set(false);
      TestBed.tick();
      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(60);
      expect(sites.rows.has('s1')).toBeFalse();
      await wait(120);
      expect(sites.rows.has('s1')).toBeTrue();
    });

    it('doubles the delay after an attempt cut by the network', async () => {
      autoDelay.set(50);
      await queueWhileDown();
      sites.down = true;
      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(120);
      // El intento ha fallado por la red: espera el doble la próxima vez
      expect(queue.syncState()).toBe('offline');
      expect(queue['autoAttempts']).toBe(1);

      sites.down = false;
      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(70);
      expect(sites.rows.has('s1')).toBeFalse();
      await wait(120);
      expect(sites.rows.has('s1')).toBeTrue();
      expect(queue['autoAttempts']).toBe(0);
    });

    it('does not start while there are failed changes to resolve', async () => {
      autoDelay.set(50);
      await queueWhileDown();
      sites.reject.add('s1');
      await queue.sync();
      expect(queue.failed()).toBe(1);
      sites.reject.clear();

      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(150);
      expect(queue.autoSyncArmed()).toBeFalse();
      expect(sites.rows.has('s1')).toBeFalse();
    });

    it('stops at the first error and keeps the rest pending', async () => {
      autoDelay.set(50);
      sites.down = true;
      await firstValueFrom(siteApi.add({ uid: 's1', name: 'A' }));
      await firstValueFrom(siteApi.add({ uid: 's2', name: 'B' }));
      sites.down = false;
      sites.reject.add('s1');
      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(150);

      expect(queue.ops().map((op) => [op.key, op.status])).toEqual([
        ['s1', 'failed'],
        ['s2', 'pending'],
      ]);
      expect(TestBed.inject(NotifyService).error).toHaveBeenCalledWith('offline.notify.autoFailed', { count: 1 });
    });

    it('is disabled with a delay of 0', async () => {
      await queueWhileDown();
      queue['onlineSignal'].set(true);
      TestBed.tick();
      await wait(100);
      expect(queue.autoSyncArmed()).toBeFalse();
      expect(queue.pending()).toBe(1);
    });
  });
});
